import{_ as a,c as n,a5 as i,o as e}from"./chunks/framework.mFcBg5UA.js";const p="/my-blog/img/e5b0046ba5fe48d5b7643124468f34a7~tplv-k3u1fbpfcp-watermark.png",t="/my-blog/img/9d7871beac3d4f13be13d2be884040be~tplv-k3u1fbpfcp-watermark.png",l="/my-blog/img/9328e5a2d5eb4aecb542b5fa5eaa2b9d~tplv-k3u1fbpfcp-watermark.png",d="/my-blog/img/31f6653369c34a4586c17f79b4e57882~tplv-k3u1fbpfcp-watermark.png",o="/my-blog/img/915d0119640f418f91ffdb4cffa4507a~tplv-k3u1fbpfcp-watermark.png",r="/my-blog/img/7d0d56e937984e06bd26563ad969ba4d~tplv-k3u1fbpfcp-watermark.png",E=JSON.parse('{"title":"原生模块调用&开发","titleTemplate":"Electron实战","description":"","frontmatter":{"outline":"deep","title":"原生模块调用&开发","titleTemplate":"Electron实战","head":[["link",{"rel":"canonical","href":"https://luffy-d-lufei.github.io/my-blog/summary/electron/native_module_call_development.html"}]]},"headers":[],"relativePath":"summary/electron/native_module_call_development.md","filePath":"summary/electron/native_module_call_development.md","lastUpdated":1724763287000}'),h={name:"summary/electron/native_module_call_development.md"};function c(k,s,u,g,b,m){return e(),n("div",null,s[0]||(s[0]=[i('<h1 id="原生模块调用-开发" tabindex="-1">原生模块调用&amp;开发 <a class="header-anchor" href="#原生模块调用-开发" aria-label="Permalink to &quot;原生模块调用&amp;开发&quot;">​</a></h1><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p>其实在实际的开发过程中，我们会实现一些 Node.js 或者 Electron 本身无法完成的功能，在这种情况下，我们需要封装一些底层的库，比如 dll、dylib、node 二进制文件，然后供上层调用。在这里我们会着重介绍如何在 Electorn 中调用底层的模块，主要是 dll 和 node 二进制文件的调用。</p><h2 id="dylib、dll-的调用" tabindex="-1">dylib、dll 的调用 <a class="header-anchor" href="#dylib、dll-的调用" aria-label="Permalink to &quot;dylib、dll 的调用&quot;">​</a></h2><p>dll 的调用其实很简单，有些时候环境引来的问题会比较麻烦。在 npm 仓库中也有很多调用 DLL 的库，至于怎么选择其实看自己，现在比较常见，使用最多的应该属<a href="https://github.com/node-ffi-napi/node-ffi-napi" target="_blank" rel="noreferrer">ffi-napi</a>。在不同平台调用的文件不一样<code>OS X</code>就是<code>.dylib</code>文件,<code>Windows</code>就是<code>.dll</code>,<code>Linux</code>就是<code>.so</code>,但是我们不使用<code>ffi-napi</code>,最主要的原因是环境会搞得你很头疼，如果<code>node-gyp</code>的安装有问题，就会让你非常烦躁，有的时候解决环境问题会花费大量时间，我踩过坑，所以不推荐。这里推荐使用<a href="https://koffi.dev/benchmarks" target="_blank" rel="noreferrer">Koffi</a>,依赖项少，速度很快，下面有个粗略的对比。</p><p><img src="'+p+'" alt="perf_linux_20220812.png"></p><p><img src="'+t+`" alt="perf_windows_20220812.png"></p><h3 id="构建-dylib、dll-文件" tabindex="-1">构建 dylib、dll 文件 <a class="header-anchor" href="#构建-dylib、dll-文件" aria-label="Permalink to &quot;构建 dylib、dll 文件&quot;">​</a></h3><p>我本地的环境是<code>OS X</code>,我们为了演示方便,就以构建<code>dylib</code>为例子。我们写一个简单的 C 函数就可以做验证了,我们可以在项目跟目录下新建一个<code>resources</code>目录,然后创建一个<code>sum.c</code>文件，内容如下</p><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#include</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &lt;stdint.h&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#if</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> defined</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">WIN32</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">||</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> defined</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">_WIN32</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#define</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> EXPORT</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> __declspec</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(dllexport)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#else</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#define</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> EXPORT</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#endif</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">EXPORT </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">uint64_t</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sum</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> a</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> b</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> a </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> b;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>然后你可以执行</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -dynamiclib -undefined suppress -flat_namespace sum.c -o sum.dylib</span></span></code></pre></div><p>这样就会构建一个<code>sum.dylib</code>文件，下面我们就可以愉快的调用它了。</p><p>当然如果你是 windows 的话，可以执行</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cl.exe /D_USRDLL /D_WINDLL sum.c /link /DLL /OUT:sum.dll</span></span></code></pre></div><h3 id="node-调用-dylib" tabindex="-1">node 调用.dylib <a class="header-anchor" href="#node-调用-dylib" aria-label="Permalink to &quot;node 调用.dylib&quot;">​</a></h3><p>我们先安装<code>koffi</code></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pnpm i koffi</span></span></code></pre></div><p>然后就可以很愉快的使用了。在<code>src</code>下新建一个<code>native</code>的目录，添加<code>index.ts</code>,koffi 使用非常简单</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import koffi from &#39;koffi&#39;</span></span>
<span class="line"><span>import path from &#39;path&#39;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>const sumLib = koffi.load(path.resolve(</span></span>
<span class="line"><span>  __dirname,</span></span>
<span class="line"><span>  &quot;../../resources/sum.dylib&quot;</span></span>
<span class="line"><span>))</span></span>
<span class="line"><span></span></span>
<span class="line"><span>const nativeSum = sumLib.stdcall(&#39;sum&#39;,&#39;int&#39;,[&#39;int&#39;,&#39;int&#39;])</span></span>
<span class="line"><span></span></span>
<span class="line"><span>export const callNativeSum = (a:number,b:number) =&gt; {</span></span>
<span class="line"><span>  return nativeSum(a,b)</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>这里需要注意一个点，就是我们需要改动一下<code>config/vite/main.js</code>中<code>rollupOptions</code>的<code>external</code>,把 koffi 导入包转成外部依赖，不然在构建的时候会报错。</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rollupOptions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  external</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;electron&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;koffi&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">builtinModules],</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  output</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    entryFileNames</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;[name].cjs&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>到这里 electron 调用 dylib、dll 的简单功能就实现了。当然我们这里还会介绍用 Rust 的方式来让你做底层的功能。</p><h2 id="桥接-rust" tabindex="-1">桥接 Rust <a class="header-anchor" href="#桥接-rust" aria-label="Permalink to &quot;桥接 Rust&quot;">​</a></h2><p>至于为什么要选择 Rust 实现,其实也不是为了学习 Rust 而 Rust,是因为在开发的过程中的确遇到了瓶颈，然后用 Rust 来处理了一些问题,其实也是多了一种选择，特别是处理耗时任务的时候，Rust 表现非常优异，下面我们就来尝试在 Electron 中通过桥接的方式来调用 Rust 的方法。</p><h3 id="rust-是什么" tabindex="-1">Rust 是什么 <a class="header-anchor" href="#rust-是什么" aria-label="Permalink to &quot;Rust 是什么&quot;">​</a></h3><p>两个链接告诉你，环境的搭建步骤和方式也告诉你了：</p><p><a href="https://www.rust-lang.org/zh-CN/learn/get-started" target="_blank" rel="noreferrer">https://www.rust-lang.org/zh-CN/learn/get-started</a></p><p><a href="https://course.rs/about-book.html" target="_blank" rel="noreferrer">https://course.rs/about-book.html</a></p><p>只有把环境搭建好，才可以开始下面的步骤哦。</p><h3 id="如何让-rust-和-node-打通" tabindex="-1">如何让 Rust 和 Node 打通 <a class="header-anchor" href="#如何让-rust-和-node-打通" aria-label="Permalink to &quot;如何让 Rust 和 Node 打通&quot;">​</a></h3><p>经过调研，我们最终选择了<a href="https://napi.rs/docs/introduction/getting-started" target="_blank" rel="noreferrer">@napi-rs/cli</a></p><p>首先全局安装一下@napi-rs/cli 脚手架</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pnpm add -g @napi-rs/cli</span></span></code></pre></div><p>然后用<code>napi new</code>创建一个新的项目，当然，如果你有成熟的分包管理工具也可以在原项目下创建项目，后面在打包构建的时候整合，我们这个为了方便简单演示其原理我们就新建一个项目。</p><p><img src="`+l+'" alt="截屏2023-02-28 20.03.18.png"> 这里我们就选择所有平台，简直就是跨端大杀器。</p><p>创建项目后会这样</p><p><img src="'+d+`" alt="截屏2023-02-28 20.07.47.png"></p><p>这里我们可以在<code>sum</code>的下面加一个减法的函数<code>subtraction</code>,测试一下它的易用性</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#[napi]</span></span>
<span class="line"><span>pub fn subtraction(a: i32, b: i32) -&gt; i32 {</span></span>
<span class="line"><span>  a - b</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>然后直接</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pnpm run build</span></span></code></pre></div><p>首次构建可能有点慢，但是后面就很快了。</p><p>构建之后会出现一个你现在构建平台的一个<code>.node</code>文件</p><p><img src="`+o+`" alt="20230228202841.jpg"></p><p>我们将其拷贝至我们原有的<code>Electron</code>项目中的<code>resources</code>目录下。</p><p>现在我们要来引用这个 node 文件，超级简单</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>const rsNative = require(path.resolve(</span></span>
<span class="line"><span>  __dirname,</span></span>
<span class="line"><span>  &quot;../../resources/rs-native.darwin-x64.node&quot;</span></span>
<span class="line"><span>))</span></span>
<span class="line"><span></span></span>
<span class="line"><span>export const rsNativeSum = (a:number,b:number) =&gt; {</span></span>
<span class="line"><span>  return rsNative.sum(a,b)</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>export const rsNativeSubtraction = (a:number,b:number) =&gt; {</span></span>
<span class="line"><span>  return rsNative.subtraction(a,b)</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>是不是感觉上层调用非常方便，不用关心数据类型。</p><p>这是现在的目录结构</p><p><img src="`+r+'" alt="截屏2023-02-28 21.12.33.png"></p><h2 id="结语" tabindex="-1">结语 <a class="header-anchor" href="#结语" aria-label="Permalink to &quot;结语&quot;">​</a></h2><p>到这里，我们基本就打通了 Electron 调用 dll,dylib,rust 构建的 node 文件的流程了。不过后续相关的构建在这个地方还有相应的改动，我们在构建那一块再细细描述。其实 Electron 打通了底层的逻辑就会非常强大，这样可以做的事情会非常多。</p>',53)]))}const f=a(h,[["render",c]]);export{E as __pageData,f as default};
